<script setup>
import {ref} from 'vue'
import Icon from './Icon.vue'
import {state,run,notify,load,stampLabel} from '../composables/useWorkspace'
import {api} from '../services/api'
import {currentCloudUser,logout,verifyEmail,refreshUser,firebaseMessage} from '../services/firebase'
const settings=ref({...state.settings}),confirmImport=ref(false),verified=ref(currentCloudUser()?.emailVerified),accountBusy=ref(false)
async function accountAction(fn,message){accountBusy.value=true;try{await fn();notify(message)}catch(error){notify(firebaseMessage(error))}finally{accountBusy.value=false}}
async function importOld(){const result=await run(()=>api.importLocal(),'Đã nhập dữ liệu SQLite lên Firebase');if(result)confirmImport.value=false}
</script>
<template><div class="settings-layout">
<section class="surface settings-card"><div class="settings-icon"><Icon name="shield"/></div><h2>Tài khoản Firebase</h2><p>{{currentCloudUser()?.email}}</p><div class="info-row"><span>Email</span><strong>{{verified?'Đã xác minh':'Chưa xác minh'}}</strong></div><div class="button-row"><button v-if="!verified" class="button" :disabled="accountBusy" @click="accountAction(verifyEmail,'Đã gửi email xác minh. Kiểm tra hộp thư của bạn.')">Gửi email xác minh</button><button v-if="!verified" class="button" :disabled="accountBusy" @click="accountAction(async()=>{const user=await refreshUser();verified=user.emailVerified;await load()},'Đã kiểm tra trạng thái email')">Tôi đã xác minh</button><button class="button" :disabled="state.busy||accountBusy" @click="accountAction(logout,'Đã đăng xuất')"><Icon name="logout" :size="17"/>Đăng xuất</button></div><p class="footnote">Đăng xuất xóa dữ liệu đang hiển thị trong bộ nhớ. Tài khoản khác chỉ tải được workspace của họ.</p></section>
<section class="surface settings-card"><div class="settings-icon"><Icon name="cloud"/></div><h2>Dữ liệu trên Firestore</h2><p>Mỗi thao tác tạo, sửa và xóa được gửi trực tiếp lên Firebase. Không cần nhấn sao lưu.</p><div class="info-row"><span>Project</span><strong>{{state.system.project}}</strong></div><div class="path-box">users/{{state.system.uid}}/tasks<br/>users/{{state.system.uid}}/logs<br/>users/{{state.system.uid}}/events</div><button class="button" :disabled="state.busy" @click="run(()=>api.exportBackup(),'Đã xuất dữ liệu Firebase')"><Icon name="download" :size="17"/>Xuất JSON</button><p class="footnote">Bản này cần mạng khi lưu. Nhấn tải lại để lấy thay đổi mới từ thiết bị khác; chưa có chỉnh sửa offline hoặc cập nhật realtime.</p></section>
<section class="surface settings-card"><div class="settings-icon amber"><Icon name="mail"/></div><h2>Email nhắc việc trên cloud</h2><p>Lưu cấu hình vào Firebase. Chỉ gửi đến email tài khoản đã xác minh.</p><form @submit.prevent="run(()=>api.saveSettings(settings),'Đã lưu cấu hình nhắc việc')"><label class="field-label">Email nhận<input :value="currentCloudUser()?.email" readonly type="email"/></label><div class="settings-grid"><label class="field-label">Giờ nhắc<select v-model.number="settings.reminder_hour"><option v-for="n in 24" :value="n-1">{{String(n-1).padStart(2,'0')}}:00</option></select></label><label class="field-label">Múi giờ<select v-model.number="settings.utc_offset"><option :value="420">Việt Nam · UTC+7</option><option :value="0">UTC</option><option :value="480">UTC+8</option></select></label></div><label class="switch-row"><span><strong>Bật nhắc việc</strong><small>Cần xác minh email và triển khai tác vụ cloud.</small></span><input v-model="settings.reminder_enabled" type="checkbox" :disabled="!verified"/></label><p class="notice">Việc lưu cài đặt không tự triển khai tác vụ gửi mail. Cần deploy Python Cloud Function và cấu hình SMTP theo FIREBASE-SETUP.md. Sau đó nhắc việc chạy cả khi đóng app.</p><p v-if="state.system.last_reminder" class="footnote">Lần gần nhất: {{stampLabel(state.system.last_reminder.updated_at)}} · {{state.system.last_reminder.status}} · {{state.system.last_reminder.detail}}</p><button class="button primary" :disabled="state.busy">Lưu cài đặt</button></form></section>
<section class="surface settings-card"><div class="settings-icon"><Icon name="upload"/></div><h2>Nhập dữ liệu SQLite cũ</h2><p>Chỉ nhập một lần vào tài khoản Firebase chưa có task. SQLite trên máy được giữ nguyên.</p><button v-if="!confirmImport" class="button" :disabled="state.busy||!state.system.uid" @click="confirmImport=true">Nhập dữ liệu từ máy này</button><div v-else class="notice warning">Nhập task, work log và lịch sử cũ vào tài khoản <strong>{{currentCloudUser()?.email}}</strong>?<div class="button-row"><button class="button small" @click="confirmImport=false">Hủy</button><button class="button primary small" :disabled="state.busy" @click="importOld">Xác nhận nhập</button></div></div><p class="footnote">Dùng trong app desktop. Dữ liệu local cũ thuộc tài khoản Windows đang dùng; chỉ nhập nếu dữ liệu đó là của bạn. Với dữ liệu lớn, app sẽ dừng thay vì nhập một phần.</p></section>
</div></template>
